entries[473354] = { ["name"] = "Überschallknall", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie große M.A.M.A. verschießt einen Impuls aus Schallenergie auf einen Spielercharakter, der alle 0.5 Sek. 2424449 Schallschaden verursacht und Spielercharaktere im Effektbereich zum Schweigen bringt und mitzieht.\n\nDer Impuls explodiert, wenn er auf ein Hindernis trifft, und fügt Spielercharakteren innerhalb von 7 Metern 6061123 Schallschaden zu." }
