entries[473521] = { ["name"] = "Bronzebarts Braunbär", ["text"] = "Brann beschwört den Bären der Familie, der sich in den Kampf stürzt und Gegner in die Luft schleudert.\n\nDer Bär setzt dann dazu an, mehrfach heftig aufzustampfen, was Schaden verursacht und einen Bereich entstehen lässt, der die Ausweichchance und maximale Gesundheit erhöht." }
