entries[473991] = { ["name"] = "Verbleibende Elektrizität", ["text"] = "60 Meter Reichweite\nSofort\nDie 'Verbleibende Elektrizität' fügt Spielercharakteren im Bereich alle 1 Sek. 1257763 Naturschaden zu und verhindert, dass sie angreifen oder Zauber wirken." }
entries[473992] = { ["name"] = "Schützende Rinde", ["text"] = "Sofort\nVerwandelt Eure Gestalt in ein Urtum der Lehren, verhindert sämtliche Kontrollverlusteffekte, verringert Euren erlittenen Schaden um 30% und gewährt Euch Zugriff auf 'Blütenexplosion' und 'Massenblüte'. Verringert die Bewegungsgeschwindigkeit.\n\nHält 12 Sek. lang an.\n\nBlütenexplosion :\nHeilt einen Verbündeten um (910% der Zaubermacht) Gesundheit und gewährt 1 fehlenden Effekt, der regelmäßige Heilung verursacht. Wenn alle Effekte vorhanden sind, verursacht 'Blütenexplosion' stattdessen kritische Heilung.\n\nMassenblüte :\nHeilt 5 Verbündete um (585% der Zaubermacht) Gesundheit und gewährt 1 fehlenden Effekt, der regelmäßige Heilung verursacht." }
entries[473993] = { ["name"] = "Schwarzblutblitz", ["text"] = "40 Meter Reichweite\nWirken in 2.5 sek.\nVerursacht 243973 Schattenschaden und zusätzlich 3 Sek. lang alle 0.5 Sek. 17427 Schattenschaden." }
entries[473994] = { ["name"] = "Statische Aufladung", ["text"] = "60 Meter Reichweite\nWirken in 3 sek.\nTorqs Anzug verstärkt die elektrischen Ladungen, die innerhalb von 70 Metern generiert werden. Bis zum nächsten Einsatz von ' Kolossaler Zusammenstoß ' durchströmt eine elektrische Ladung die Spielercharaktere in Reichweite und verursacht alle 1 Sek. 117391 Naturschaden. Außerdem steigt die Ladung, während sich das Ziel innerhalb der Reichweite bewegt und fällt, solange es stillsteht. Bei maximaler Ladung bricht es als ' Statische Entladung ' aus." }
