entries[474086] = { ["name"] = "Prismatischer Schnappdrache", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Chamäleonartige Kreaturen können oft ihre Zellfarben an die der Außenwelt anpassen. Dieser Schnappdrache hat sich diese Fähigkeit angeeignet, aber lediglich im Hinblick auf den Inhalt seines Magens, was dem Sinnspruch 'Du bist, was du isst' eine ganz neue Bedeutung verleiht.\"\nQuest:\nEin treuer Freund\nZone:\nSireneninsel" }
