entries[474559] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nB3U13RÄUB-R\nTastet die Umgebung alle 60 Sek. oder 5 Sek. nach Kampfbeginn ab, hebt verlegte Kuriositäten hervor und lässt Gegner mit weniger als 95% Gesundheit 10 Sek. lang 4% mehr Schaden erleiden.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
