entries[474572] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nKaja'Cola-Träger\nVerlegte Kuriositäten haben jetzt einmal pro Tiefe eine Chance von 35%, 1 Kaja'Colas zu enthalten, und Brann beschwört jetzt ein Sechserpack Kaja'Cola, wenn er ein Lagerfeuer macht.\n\nEs gibt verschiedene Kaja'Cola-Geschmacksrichtungen und jede hat einen eigenen Effekt, der beim Einsammeln wirkt.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[474573] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nAbsurd großer Magnet\nWenn Brann ' Sammelwerkzeuge ' einsetzt, besteht eine Chance von 100 %, weggeworfene Panzerung zu magnetisieren. Diese Panzerung haftet an Gruppenmitgliedern und gewährt ihnen 5 % ihrer maximalen Gesundheit als Schild, der sich außerhalb des Kampfes regeneriert.\n\nSammelwerkzeuge\nBrann setzt seine Sammelwerkzeuge ein, um Spielercharakteren zu helfen, zusätzliches Gold, Erz, Leder, zusätzliche Kräuter, Fische und Schätze zu finden.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[474574] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nRaketenausrüstung mit Biotreibstoff\nGruppenmitglieder werden mit Raketenausrüstung mit Biotreibstoff ausgerüstet.\n\nBiotreibstoff\nJeder getötete Gegner füllt die Raketenausrüstung mit Biotreibstoff auf und erhöht damit 10 Sek. lang die Bewegungsgeschwindigkeit um 2 % und das Tempo um 2 %. Bis zu 10-mal stapelbar.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[474576] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nDreidimensionaler Biodrucker\nWenn Ihr einer Elitekreatur mit weniger als 40 % Gesundheit Schaden zufügt, wird eine unvollkommene Kopie dieser Kreatur mit 50 % Energie erschaffen, die an Eurer Seite kämpft. Nur 1 Kopie kann gleichzeitig existieren.\n\nDas Gerät könnte eine Fehlfunktion haben und unvollkommene Kopien Eures Begleiters erzeugen.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[474577] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nÜberladungspylon\nNach 30 Sek. Kampfdauer verursachen Gruppenmitglieder und Brann 20 Sek. lang 5 % mehr Schaden und Heilung. Kann nur einmal pro Kampf auftreten.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[474578] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nPazifistenausrüstung\nWährend des Kampfes wird für 8 Sek. ein Pilot bestimmt. Daraufhin wird die Pazifistenausrüstung MK 1 an dessen Standort abgeworfen, wodurch dieser Immunität erhält, ihm 10 Sek. lang Kontrolle über die Ausrüstung gewährt wird und Gegner in der Nähe zurückgestoßen werden.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[474579] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nKaja'Cola-Träger\nVerlegte Kuriositäten haben jetzt einmal pro Tiefe eine Chance von 45%, 2 Kaja'Colas zu enthalten, und Brann beschwört jetzt ein Sechserpack Kaja'Cola, wenn er ein Lagerfeuer macht.\n\nEs gibt verschiedene Kaja'Cola-Geschmacksrichtungen und jede hat einen eigenen Effekt, der beim Einsammeln wirkt.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
