entries[474599] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nMechasaurus-Schnellbaukasten\n' Branns episches Ei ' enthält jetzt 1 Mechasaurier, die Gegner für ( 4000 / 1000) Sek. verspotten, solange sie sich im Ei befinden.\n\nZusätzlich zu ihren üblichen Fähigkeiten stampfen Mechasaurier in regelmäßigen Abständen auf und verursachen moderaten Feuerschaden, der auf Gegner in der Nähe aufgeteilt wird. Getroffene Gegner explodieren nach 5 Sek. und erleiden moderaten Feuerschaden.\n\nBranns episches Ei\nBrann beschwört ein Teufelssaurierei. Hoffentlich schlüpft es.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[474600] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nAutomatischer Fußbombenspender\nBranns Zauber und Fähigkeiten haben die Chance, 10 Sek. lang 2 Fußbomben auf das Feld zu werfen.\n\nWenn Ihr gegen eine Fußbombe lauft, wird sie auf Euer Ziel geschleudert und fügt allen Gegnern in einem Radius von 6 Metern beträchtlichen Feuerschaden zu.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[474601] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nEinschlagsumwandlungsmatrix\nZu Kampfbeginn aktiviert Brann für 10 Sek. die Umwandlungsmatrix. Ein kleiner Anteil von sämtlichem Schaden, den die Gruppe währenddessen verursacht, erhöht den Primärwert. Die Erhöhung wird unter den Gruppenmitgliedern aufgeteilt.\n\nWenn sich die Umwandlungsmatrix deaktiviert, bleibt die Erhöhung des Primärwerts noch 10 Sek. lang bestehen. Dieser Effekt kann nur einmal alle 2 Min. auftreten.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[474602] = { ["name"] = "Sprengbrands Brüllkanone", ["text"] = "60 Meter Reichweite\nSofort\nWährend des Aufladens aktiviert Leuchtendo die Zielverfolgung, arretiert sie dann und macht sich feuerbereit. Danach feuert er für 3 Sek. einen Strahl ab, der Spielcharakteren bei Kontakt alle 0.1 Sek. 66606435 Feuerschaden zufügt und sie vernichtet." }
entries[474603] = { ["name"] = "Brisenfeder rufen" }
entries[474604] = { ["name"] = "Kill Credit - Runas Quests (NJS)" }
entries[474605] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nTaschenfabrik\nBranns Zauber und Fähigkeiten haben die Chance, die Taschenfabrik mit der Herstellung von 1 Geschütz zu beauftragen, die 10 Sek. lang Unterstützung bieten.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[474606] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGoblomagnetische Hüpfgranate\nBrann hat eine Chance, im Kampf eine goblomagnetische Hüpfgranate auf ein Ziel zu werfen, die mäßigen Naturschaden verursacht und eine Chance von 20% hat, das Ziel für 1.5 Sek. zu betäuben. Anschließend besteht eine Chance von 25%, dass die Granate zu einem neuen Ziel hüpft.\n\nDie Granate kann bedenkenlos zu Gruppenmitgliedern springen.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[474607] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nAngeklopfter Erweiterungschip\nBranns maximale Gesundheit ist um 4 % erhöht und er verursacht 20 % mehr Schaden und Heilung.\n\nIm Kampf kann Brann von mechanischen Robotern anvisiert werden, die sich zerstören oder vertreiben lassen. Wenn sie Brann erreichen, erleidet er 30 % seiner maximalen Gesundheit als Schaden und wird für 5 Sek. betäubt.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[474608] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nRückentwickelte Goblintodesbombe\nWenn die Gesundheit eines Spielcharakters während eines Kampfes unter 50% fällt, wirft Brann eine riesige Bombe, die beim Einschlag explodiert.\n\nDie Explosion stößt umstehende Gegner zurück, verlangsamt sie 5 Sek. lang um 45% und heilt Gruppenmitglieder in der Nähe um 35% ihrer maximalen Gesundheit. Kann nur einmal alle 1.5 Min. auftreten.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[474609] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nAngeklopfter Erweiterungschip\nBranns maximale Gesundheit ist um 6 % erhöht und er verursacht 25 % mehr Schaden und Heilung.\n\nIm Kampf kann Brann von mechanischen Robotern anvisiert werden, die sich zerstören oder vertreiben lassen. Wenn sie Brann erreichen, erleidet er 30 % seiner maximalen Gesundheit als Schaden und wird für 5 Sek. betäubt.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
