entries[474621] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nAutomatischer Fußbombenspender\nBranns Zauber und Fähigkeiten haben die Chance, 10 Sek. lang 3 Fußbomben auf das Feld zu werfen.\n\nWenn Ihr gegen eine Fußbombe lauft, wird sie auf Euer Ziel geschleudert und fügt allen Gegnern in einem Radius von 6 Metern beträchtlichen Feuerschaden zu.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
