entries[474624] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nEinschlagsumwandlungsmatrix\nZu Kampfbeginn aktiviert Brann für 10 Sek. die Umwandlungsmatrix. Ein kleiner Anteil von sämtlichem Schaden, den die Gruppe währenddessen verursacht, erhöht den Primärwert. Die Erhöhung wird unter den Gruppenmitgliedern aufgeteilt.\n\nWenn sich die Umwandlungsmatrix deaktiviert, bleibt die Erhöhung des Primärwerts noch 15 Sek. lang bestehen. Dieser Effekt kann nur einmal alle 2 Min. auftreten.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[474625] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nEinschlagsumwandlungsmatrix\nZu Kampfbeginn aktiviert Brann für 15 Sek. die Umwandlungsmatrix. Ein kleiner Anteil von sämtlichem Schaden, den die Gruppe währenddessen verursacht, erhöht den Primärwert. Die Erhöhung wird unter den Gruppenmitgliedern aufgeteilt.\n\nWenn sich die Umwandlungsmatrix deaktiviert, bleibt die Erhöhung des Primärwerts noch 15 Sek. lang bestehen. Dieser Effekt kann nur einmal alle 2 Min. auftreten.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[474626] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nEinschlagsumwandlungsmatrix\nZu Kampfbeginn aktiviert Brann für 20 Sek. die Umwandlungsmatrix. Ein kleiner Anteil von sämtlichem Schaden, den die Gruppe währenddessen verursacht, erhöht den Primärwert. Die Erhöhung wird unter den Gruppenmitgliedern aufgeteilt.\n\nWenn sich die Umwandlungsmatrix deaktiviert, bleibt die Erhöhung des Primärwerts noch 20 Sek. lang bestehen. Dieser Effekt kann nur einmal alle 2 Min. auftreten.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[474627] = { ["name"] = "Hinzufügen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nMechasaurus-Schnellbaukasten\n' Branns episches Ei ' enthält jetzt 2 Mechasaurier, die Gegner für ( 6000 / 1000) Sek. verspotten, solange sie sich im Ei befinden.\n\nZusätzlich zu ihren üblichen Fähigkeiten stampfen Mechasaurier in regelmäßigen Abständen auf und verursachen moderaten Feuerschaden, der auf Gegner in der Nähe aufgeteilt wird. Getroffene Gegner explodieren nach 5 Sek. und erleiden moderaten Feuerschaden.\n\nBranns episches Ei\nBrann beschwört ein Teufelssaurierei. Hoffentlich schlüpft es.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
