entries[1213303] = { ["name"] = "Dr. Schrottheil", ["text"] = "Ca. 3 Procs pro Minute\nEure Heilzauber und -fähigkeiten haben eine Chance, Dr. Schrottheil zu beschwören, der Euer Ziel zusätzlich um 487 Gesundheit heilt.\n\nWenn die Gesundheit eines Verbündeten in der Nähe unter 35% fällt, kommt Dr. Schrottheil zum Einsatz und leistet die Notversorgung, um ihn um 1900 Gesundheit zu heilen. Dieser Effekt kann nur einmal alle 1 Min. ausgelöst werden." }
