entries[1213620] = { ["name"] = "22H-Rennreifen", ["text"] = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nHaufen rostigen Schrotts (50), Handvoll Bismutbolzen (32), Launische Verdrahtung (6), Kreisende Ausrüstung (12), Entropieverstärker (2)\nVerkäufer:\nSmaks Oberskimmer\nZone:\nLorenhall\nKosten:\n150\n\n22H-Rennreifen\nBenutzen: Installiert diese Reifen, um die Wendekapazitäten Eures 99-G-Genickbrechers auf Kosten der Stabilität beim Driften zu steigern.\n80\n\"Voller Kontakt mit der Oberfläche für maximale Reibung.\"" }
entries[1213621] = { ["name"] = "Raketenregen", ["text"] = "Unbegrenzte Reichweite\nWirken in 3.5 sek. 12 sek. Abklingzeit\nDer Schredder feuert 10 Sek. lang Raketen auf zufällige Ziele ab. Verursacht beim Einschlag 1215838 Feuerschaden und 10 Sek. lang alle 1 Sek. 754658 zusätzlichen Feuerschaden." }
